@import '../../utils/radius.css';
@import '../../utils/interaction-fill.css';
@import '../../utils/focus-ring.css';
@import '../../utils/control-inactive.css';
@import '../../utils/forced-colors.css';

:host {
  --_disclosure-inset-inline: var(--dimension-space-200);
  --_disclosure-trailing-gap: var(--dimension-space-100);
  --_disclosure-duration: var(--effect-animation-duration-short-3);
  position: relative;
  display: block;
  box-sizing: border-box;
  min-width: 0;
  color: var(--color-foreground-primary);
  border-bottom: var(--dimension-stroke-width-012) solid var(--color-border-tertiary);
}

/* Card surface, matching CardSetting's split shadow + highlight recipe. */
:host(.disclosure--contained) {
  overflow: hidden;
  border-bottom: 0;
  border-radius: var(--ds-radius-card);
  background-color: var(--color-background-primary);
  box-shadow: var(--effect-shadow-elevated-sm);
}

:host(.disclosure--contained)::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  box-shadow: var(--effect-highlight-elevated-sm);
  pointer-events: none;
}

/*
 * Heading, trailing status, then the chevron, matching Table and Live Map group
 * rows. The trigger's hit area covers the whole row; the trailing slot sits
 * above it so its own controls keep their semantics.
 */
.disclosure-header {
  display: flex;
  cursor: default;
  align-items: center;
  gap: var(--_disclosure-trailing-gap);
  min-width: 0;
  padding-inline-end: var(--_disclosure-inset-inline);
}

.disclosure-heading-level {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  font: inherit;
}

.disclosure-trigger {
  display: flex;
  align-items: center;
  box-sizing: border-box;
  width: 100%;
  min-block-size: var(--dimension-size-600);
  margin: 0;
  padding-block: var(--dimension-space-150);
  padding-inline: var(--_disclosure-inset-inline) 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  -webkit-user-select: none;
  user-select: none;
}

/*
 * The wash and focus ring paint on the whole header row so a trailing slot is
 * covered too; only the trigger button drives them. Instant on enter, eased
 * fade on leave (shared nav/tab timing).
 */
.disclosure-header::after {
  transition: background var(--effect-motion-short-3);
}

@media (hover: hover) and (pointer: fine) {
  .disclosure-header:has(.disclosure-trigger:hover)::after {
    background: var(--ds-interaction-hover);
    transition: none;
  }
}

.disclosure-header:has(.disclosure-trigger:active)::after {
  background: var(--ds-interaction-pressed);
  transition: none;
}

.disclosure-trigger::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
}

.disclosure-trigger:focus-visible {
  outline: none;
}

.disclosure-header:has(.disclosure-trigger:focus-visible)::after {
  outline: var(--ds-focus-ring-width) solid var(--ds-focus-ring-color);
  outline-offset: calc(-1 * var(--ds-focus-ring-width));
}

:host(.disclosure--contained) .disclosure-header::after {
  border-radius: var(--ds-radius-card) var(--ds-radius-card) 0 0;
}

:host(.disclosure--contained:not(.disclosure--open)) .disclosure-header::after {
  border-radius: var(--ds-radius-card);
}

/* The count and chevron let clicks and hover through to the trigger's hit area. */
.disclosure-count,
.disclosure-chevron {
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  pointer-events: none;
}

.disclosure-chevron {
  color: var(--color-foreground-secondary);
}

/* ChevronDown while collapsed, turning to ChevronUp when open. */
:host(.disclosure--open) .disclosure-chevron {
  transform: rotate(180deg);
}

.disclosure-copy {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: var(--dimension-space-025);
  min-width: 0;
}

.disclosure-trailing {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  gap: var(--dimension-space-050);
}

.disclosure-trailing--empty {
  display: none;
}

.disclosure-trailing slot {
  display: contents;
}

/* Height animates through grid rows so content never needs measuring. */
.disclosure-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition:
    grid-template-rows var(--_disclosure-duration) var(--effect-animation-easing-ease-in-out),
    visibility 0s linear var(--_disclosure-duration);
  visibility: hidden;
}

.disclosure-panel--open {
  grid-template-rows: 1fr;
  transition:
    grid-template-rows var(--_disclosure-duration) var(--effect-animation-easing-ease-in-out),
    visibility 0s linear 0s;
  visibility: visible;
}

.disclosure-panel__clip {
  min-height: 0;
  overflow: hidden;
}

/* Content shares the heading's inline inset on both edges. */
.disclosure-content {
  padding: 0 var(--_disclosure-inset-inline) var(--dimension-space-200);
  opacity: 0;
  transition: opacity var(--_disclosure-duration) var(--effect-animation-easing-ease-out);
}

.disclosure-panel--open .disclosure-content {
  opacity: 1;
}

@media (prefers-reduced-motion: no-preference) {
  .disclosure-chevron {
    transition: transform var(--effect-motion-short-3);
  }
}

@media (prefers-reduced-motion: reduce) {
  .disclosure-panel,
  .disclosure-panel--open,
  .disclosure-content {
    transition: none;
  }
}

@media (forced-colors: active) {
  :host(.disclosure--contained) {
    outline: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    outline-offset: calc(-1 * var(--dimension-stroke-width-012));
  }

  :host(.disclosure--contained)::after {
    box-shadow: none;
  }
}

import { Component, Prop, State, Event, EventEmitter, Element, h, Host } from '@stencil/core';

export type DisclosureVariant = 'flush' | 'contained';
export type DisclosureHeadingLevel = 2 | 3 | 4 | 5 | 6;

let disclosureIdCounter = 0;

@Component({
  tag: 'ds-disclosure',
  styleUrl: 'Disclosure.css',
  scoped: true,
})
export class Disclosure {
  @Element() el!: HTMLElement;

  /** Whether the content is shown. The component mutates this when the trigger is activated. */
  @Prop({ mutable: true, reflect: true }) open: boolean = false;
  @Prop() heading!: string;
  /** Optional supporting copy shown below the heading inside the trigger. */
  @Prop() description: string = '';
  /** Heading level that wraps the trigger, matching the surrounding document outline. */
  @Prop() headingLevel: DisclosureHeadingLevel = 3;
  /** `flush` separates stacked sections with a divider; `contained` sits on its own card surface. */
  @Prop() variant: DisclosureVariant = 'flush';
  @Prop() isInactive: boolean = false;
  /** Count shown before the chevron, as in Table group rows. Part of the toggle hit area. */
  @Prop() count: number | string | undefined;

  @State() private hasTrailing: boolean = false;

  /** Emitted after the user toggles the section; detail is the new open state. */
  @Event() dsToggle!: EventEmitter<boolean>;

  private readonly baseId = `ds-disclosure-${++disclosureIdCounter}`;
  private readonly panelId = `${this.baseId}-panel`;
  private readonly triggerId = `${this.baseId}-trigger`;
  private readonly countId = `${this.baseId}-count`;

  componentWillLoad() {
    this.hasTrailing = this.el.querySelector('[slot="trailing"]') !== null;
  }

  private toggle = () => {
    if (this.isInactive) return;
    this.open = !this.open;
    this.dsToggle.emit(this.open);
  };

  private updateTrailing(slot: HTMLSlotElement) {
    this.hasTrailing =
      slot
        .assignedNodes()
        .some(node => node.nodeType !== Node.TEXT_NODE || !!node.textContent?.trim()) ||
      this.el.querySelector('[slot="trailing"]') !== null;
  }

  render() {
    const HeadingTag = `h${this.headingLevel}` as 'h3';
    const hasCount = this.count !== undefined && this.count !== null && `${this.count}` !== '';
    return (
      <Host
        class={{
          'disclosure--contained': this.variant === 'contained',
          'disclosure--open': this.open,
        }}
      >
        <div class="disclosure-header ds-interaction-fill">
          <HeadingTag class="disclosure-heading-level">
            <button
              id={this.triggerId}
              type="button"
              class={{
                'disclosure-trigger': true,
                'ds-control-inactive': this.isInactive,
              }}
              aria-expanded={this.open ? 'true' : 'false'}
              aria-controls={this.panelId}
              aria-disabled={this.isInactive ? 'true' : undefined}
              aria-describedby={hasCount ? this.countId : undefined}
              onClick={this.toggle}
            >
              <span class="disclosure-copy ds-interaction-fill__content">
                <ds-text
                  class="disclosure-title"
                  as="span"
                  variant="text-body-medium"
                  emphasis
                  color="primary"
                  wrap="wrap"
                >
                  {this.heading}
                </ds-text>
                {this.description ? (
                  <ds-text
                    class="disclosure-description"
                    as="span"
                    variant="text-body-small"
                    color="secondary"
                    wrap="wrap"
                  >
                    {this.description}
                  </ds-text>
                ) : null}
              </span>
            </button>
          </HeadingTag>
          <div
            class={{ 'disclosure-trailing': true, 'disclosure-trailing--empty': !this.hasTrailing }}
          >
            <slot
              name="trailing"
              onSlotchange={(event: Event) =>
                this.updateTrailing(event.currentTarget as HTMLSlotElement)
              }
            />
          </div>
          {hasCount ? (
            <ds-text
              id={this.countId}
              class="disclosure-count ds-interaction-fill__content"
              as="span"
              variant="text-body-medium"
              color="secondary"
              aria-hidden="true"
            >
              {this.count}
            </ds-text>
          ) : null}
          <ds-icon
            class="disclosure-chevron ds-interaction-fill__content"
            name="ChevronDown"
            size="md"
            color="inherit"
            aria-hidden="true"
          />
        </div>
        <div
          id={this.panelId}
          class={{ 'disclosure-panel': true, 'disclosure-panel--open': this.open }}
          role="region"
          aria-labelledby={this.triggerId}
          inert={!this.open}
        >
          <div class="disclosure-panel__clip">
            <div class="disclosure-content">
              <slot />
            </div>
          </div>
        </div>
      </Host>
    );
  }
}
